// Reserves 200px of scroll but pins its last 56px:
// the three extents deliberately disagree.
class RenderPinnedBanner extends RenderSliver {
  static const double _full = 200;
  static const double _pinned = 56;

  @override
  void performLayout() {
    final c = constraints;                  // SliverConstraints, from the viewport
    final painted = (_full - c.scrollOffset).clamp(_pinned, _full);

    geometry = SliverGeometry(
      scrollExtent: _full,                  // what the scrollbar measures
      // Exceed what the viewport has left and the assert fires.
      paintExtent: painted.clamp(0.0, c.remainingPaintExtent),

      // ❌ layoutExtent: painted
      //    -> everything below sits 56px too low for the rest of the scroll
      // ✅ once pinned we take no layout space; content scrolls under us
      layoutExtent: (_full - c.scrollOffset).clamp(0.0, c.remainingPaintExtent),

      maxPaintExtent: _full,
      maxScrollObstructionExtent: _pinned,  // what stays covered when pinned
      hasVisualOverflow: true,
    );
  }

  @override
  void paint(PaintingContext context, Offset offset) {
    if (!geometry!.visible) return;
    context.canvas.drawRect(
      offset & Size(constraints.crossAxisExtent, geometry!.paintExtent),
      Paint()..color = const Color(0xFF3F51B5),
    );
  }
}

