class _FeedHeaderState extends State<FeedHeader> {
  final _scroll = ScrollController();
  final _collapsed = ValueNotifier<bool>(false);  // derived: flips twice, not 800x

  @override
  void initState() {
    super.initState();
    _scroll.addListener(_onScroll);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      // ❌ jumpTo here without the callback:
      //    'ScrollController not attached to any scroll views.'
      if (_scroll.hasClients) _scroll.jumpTo(widget.savedOffset);
    });
  }

  // ❌ setState(() {}) here would rebuild the page on every scroll tick.
  void _onScroll() => _collapsed.value = _scroll.offset > 120;

  Future<void> _backToTop() async {
    if (!_scroll.hasClients) return;   // this tab may not be built yet
    // Completes when the activity ends — including the user grabbing the
    // list mid-flight. Not a promise that we reached 0.
    await _scroll.animateTo(0,
        duration: const Duration(milliseconds: 300), curve: Curves.easeOut);
  }

  @override
  void dispose() {
    _scroll.removeListener(_onScroll);
    _scroll.dispose();
    _collapsed.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Stack(children: [
        ListView.builder(
          controller: _scroll,
          itemCount: widget.posts.length,
          itemBuilder: (_, i) => PostTile(post: widget.posts[i]),
        ),
        // ✅ only this subtree rebuilds, and only when the flag flips
        ValueListenableBuilder<bool>(
          valueListenable: _collapsed,
          builder: (_, collapsed, child) => AnimatedOpacity(
            opacity: collapsed ? 0 : 1,
            duration: const Duration(milliseconds: 150),
            child: child,
          ),
          child: const TitleBar(),
        ),
      ]);
}

class Feed extends StatelessWidget {
  const Feed({super.key, required this.posts, required this.onLoadMore});
  final List<Post> posts;
  final VoidCallback onLoadMore;

  bool _onScroll(ScrollNotification n) {
    // ❌ Without this line the horizontal carousel below triggers load-more.
    if (n.depth != 0) return false;          // 0 == the nearest Scrollable
    if (n is ScrollUpdateNotification && n.metrics.extentAfter < 600) {
      onLoadMore();
    }
    return false;                            // false = keep bubbling upward
  }

  @override
  Widget build(BuildContext context) {
    return RefreshIndicator(
      // The inner list of a NestedScrollView is one level deeper than the
      // default predicate (depth == 0) accepts.
      notificationPredicate: (n) => n.depth == 1,
      onRefresh: () => context.read<FeedModel>().refresh(),
      child: NotificationListener<ScrollNotification>(
        onNotification: _onScroll,
        child: NestedScrollView(
          headerSliverBuilder: (_, __) => const [SliverAppBar(pinned: true)],
          body: ListView.builder(
            itemCount: posts.length,
            itemBuilder: (_, i) => posts[i].isCarousel
                // A second Scrollable: its notifications arrive at depth > 0
                ? SizedBox(
                    height: 160,
                    child: ListView.builder(
                      scrollDirection: Axis.horizontal,
                      itemCount: posts[i].related.length,
                      itemBuilder: (_, j) => Card(child: Text('$j')),
                    ),
                  )
                : PostTile(post: posts[i]),
          ),
        ),
      ),
    );
  }
}

class SnapPhysics extends ScrollPhysics {
  const SnapPhysics({required this.itemExtent, super.parent});
  final double itemExtent;

  // Required so the chain can be rebuilt when the physics is applied.
  @override
  SnapPhysics applyTo(ScrollPhysics? ancestor) =>
      SnapPhysics(itemExtent: itemExtent, parent: buildParent(ancestor));

  double _target(ScrollMetrics position, double velocity) {
    final settled = position.pixels + 0.15 * velocity;  // where a fling lands
    final index = (settled / itemExtent).round();
    return (index * itemExtent)
        .clamp(position.minScrollExtent, position.maxScrollExtent);
  }

  @override
  Simulation? createBallisticSimulation(ScrollMetrics position, double velocity) {
    // Leave overscroll to the parent; we only snap inside the range.
    if ((velocity <= 0 && position.pixels <= position.minScrollExtent) ||
        (velocity >= 0 && position.pixels >= position.maxScrollExtent)) {
      return super.createBallisticSimulation(position, velocity);
    }
    final target = _target(position, velocity);
    final tolerance = toleranceFor(position);
    if ((target - position.pixels).abs() < tolerance.distance) {
      return null;                    // close enough: let the position settle
    }
    return ScrollSpringSimulation(spring, position.pixels, target, velocity,
        tolerance: tolerance);
  }
}

