class _SectionHeader extends SliverPersistentHeaderDelegate {
  const _SectionHeader({required this.title, required this.unread});
  final String title;
  final int unread;

  @override double get minExtent => 56;
  @override double get maxExtent => 180;

  @override
  Widget build(BuildContext context, double shrinkOffset, bool overlapsContent) {
    // 0 = fully expanded, 1 = fully collapsed
    final t = (shrinkOffset / (maxExtent - minExtent)).clamp(0.0, 1.0);
    return Material(
      // true only while rows are actually sliding underneath the pinned header
      elevation: overlapsContent ? 3 : 0,
      color: Theme.of(context).colorScheme.surface,
      child: Padding(
        padding: EdgeInsets.lerp(
          const EdgeInsets.fromLTRB(24, 56, 24, 20),
          const EdgeInsets.fromLTRB(16, 16, 16, 12),
          t,
        )!,
        child: Align(
          alignment: Alignment.bottomLeft,
          child: Text('$title ($unread)',
              style: TextStyle(fontSize: 32 - 12 * t, fontWeight: FontWeight.w600)),
        ),
      ),
    );
  }

  // asked only when a NEW delegate instance arrives — compare what build() reads
  @override
  bool shouldRebuild(_SectionHeader old) =>
      title != old.title || unread != old.unread;
}

