class _PinnedColumnTableState extends State<PinnedColumnTable> {
  final _left = ScrollController();
  final _right = ScrollController();
  bool _syncing = false;

  @override
  void initState() {
    super.initState();
    _left.addListener(() => _mirror(_left, _right));
    _right.addListener(() => _mirror(_right, _left));
  }

  void _mirror(ScrollController from, ScrollController to) {
    if (_syncing || !to.hasClients) return;
    _syncing = true;                       // without the flag the echo loops
    // jumpTo does not clamp; an over-scrolled leader would throw the follower
    to.jumpTo(from.offset.clamp(
      to.position.minScrollExtent,
      to.position.maxScrollExtent,
    ));
    _syncing = false;
  }

  @override
  void dispose() {
    _left.dispose();
    _right.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Row(children: [
        SizedBox(width: 140, child: ListView.builder(
          controller: _left, itemExtent: 48, itemCount: rows.length,
          itemBuilder: (_, i) => LabelCell(rows[i]))),
        Expanded(child: ListView.builder(
          controller: _right, itemExtent: 48, itemCount: rows.length,
          itemBuilder: (_, i) => ValuesRow(rows[i]))),
      ]);
}

