class _TaskListState extends State<TaskList> {
  final List<Task> _tasks = seedTasks();
  final List<Task> _done = doneTasks();

  @override
  Widget build(BuildContext context) => CustomScrollView(slivers: [
        const SliverAppBar(pinned: true, title: Text('Today')),
        SliverReorderableList(
          itemCount: _tasks.length,
          onReorder: (oldIndex, newIndex) => setState(() {
            // newIndex is measured with the dragged item still in the list
            if (newIndex > oldIndex) newIndex -= 1;
            _tasks.insert(newIndex, _tasks.removeAt(oldIndex));
          }),
          proxyDecorator: (child, index, animation) =>
              Material(elevation: 6, child: child),
          itemBuilder: (context, index) {
            final task = _tasks[index];
            return ListTile(
              key: ValueKey(task.id),          // ✅ identity, not position
              title: Text(task.title),
              trailing: ReorderableDragStartListener(
                index: index,
                child: const Icon(Icons.drag_handle),
              ),
            );
          },
        ),
        SliverList.builder(
          itemCount: _done.length,
          itemBuilder: (_, i) => DoneTile(_done[i]),
        ),
      ]);
}

