class _ChatState extends State<Chat> {
  static const _centerKey = ValueKey<String>('live');
  final _controller = ScrollController();
  final List<Message> _older = [];   // index 0 = nearest the anchor, walking back
  final List<Message> _live = [];    // index 0 = the anchor, growing downward

  Future<void> _loadHistory() async {
    final page = await repo.before(_older.isEmpty ? _live.first : _older.last);
    // ✅ no jump: these land at negative scroll offsets, above the zero point
    setState(() => _older.addAll(page));
  }

  void _onIncoming(Message m) {
    final p = _controller.position;
    final wasAtBottom = p.pixels >= p.maxScrollExtent - 24;
    setState(() => _live.add(m));
    if (wasAtBottom) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _controller.jumpTo(_controller.position.maxScrollExtent);
      });
    }
  }

  @override
  void dispose() { _controller.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) => CustomScrollView(
        controller: _controller,
        center: _centerKey,      // scroll offset 0 starts at this sliver
        anchor: 0.0,
        slivers: [
          // laid out backwards from the centre — every offset here is negative
          SliverList.builder(
            itemCount: _older.length,
            itemBuilder: (_, i) => Bubble(_older[i]),
          ),
          SliverList.builder(
            key: _centerKey,     // the key goes on the sliver, not on a child
            itemCount: _live.length,
            itemBuilder: (_, i) => Bubble(_live[i]),
          ),
        ],
      );
}

// ❌ ListView.builder over one list + messages.insertAll(0, page):
//    each prepended message adds its height above the viewport, so the thread
//    lurches down by a screenful every time a history page arrives.

/// Consumes its child's height of scroll but paints it at a fraction of the
/// scroll speed — a parallax backdrop no built-in sliver gives you.
class SliverParallax extends SingleChildRenderObjectWidget {
  const SliverParallax({super.key, super.child, this.factor = 0.5});
  final double factor;

  @override
  RenderSliverParallax createRenderObject(BuildContext context) =>
      RenderSliverParallax(factor: factor);

  @override
  void updateRenderObject(BuildContext context, RenderSliverParallax ro) =>
      ro.factor = factor;
}

class RenderSliverParallax extends RenderSliverSingleBoxAdapter {
  RenderSliverParallax({required double factor}) : _factor = factor;

  double _factor;
  set factor(double v) {
    if (v == _factor) return;
    _factor = v;
    markNeedsLayout();
  }

  @override
  void performLayout() {
    final RenderBox? child = this.child;
    if (child == null) {
      geometry = SliverGeometry.zero;     // still has to be assigned
      return;
    }
    child.layout(constraints.asBoxConstraints(), parentUsesSize: true);
    final double extent = child.size.height;   // vertical axis assumed

    // does the clamping against scrollOffset / remainingPaintExtent for you
    final double painted = calculatePaintOffset(constraints, from: 0, to: extent);

    geometry = SliverGeometry(
      scrollExtent: extent,
      paintExtent: painted,                      // <= remainingPaintExtent
      maxPaintExtent: extent,                    // >= paintExtent
      cacheExtent: calculateCacheOffset(constraints, from: 0, to: extent),
      // drawn behind the scroll by (1 - factor) of the offset
      paintOrigin: constraints.scrollOffset * (1 - _factor),
      hasVisualOverflow: extent > constraints.remainingPaintExtent,
    );
    setChildParentData(child, constraints, geometry!);
  }
}

